/// `TW_STATUS`; `Data` stands for the union of `Data` and `Reserved`.
#[repr(C, packed(2))]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct TW_STATUS {
    pub ConditionCode: u16,
    pub Data: u16,
}

/// `TW_INFO`: one item of extended image info. `ReturnCode` stands for the
/// union of `ReturnCode` and the deprecated `CondCode`.
#[repr(C, packed(2))]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct TW_INFO {
    pub InfoID: u16,
    pub ItemType: u16,
    pub NumItems: u16,
    pub ReturnCode: u16,
    pub Item: usize,
}

/// `TW_EXTIMAGEINFO` with room for one `TW_INFO`; a request for more is a
/// larger block laid out the same way.
#[repr(C, packed(2))]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct TW_EXTIMAGEINFO {
    pub NumInfos: u32,
    pub Info: [TW_INFO; 1],
}

