impl Default for TW_DEVICEEVENT {
    fn default() -> Self {
        TW_DEVICEEVENT {
            Event: 0,
            DeviceName: [0; 256],
            BatteryMinutes: 0,
            BatteryPercentage: 0,
            PowerSupply: 0,
            XResolution: TW_FIX32::default(),
            YResolution: TW_FIX32::default(),
            FlashUsed2: 0,
            AutomaticCapture: 0,
            TimeBeforeFirstCapture: 0,
            TimeBetweenCaptures: 0,
        }
    }
}

// What follows holds or calls the DSM's code, and stays inside the crate.

/// `DSMENTRYPROC`: the DSM's one entry point. `TW_CALLINGSTYLE` is `PASCAL`:
/// `__stdcall` on x86, `extern "system"` in Rust.
#[allow(dead_code)]
pub(crate) type DsmEntryProc = unsafe extern "system" fn(
    origin: *mut TW_IDENTITY,
    dest: *mut TW_IDENTITY,
    dg: u32,
    dat: u16,
    msg: u16,
    data: *mut c_void,
) -> u16;
/// `TWAINCALLBACKPROC`: the application's callback, with the entry point's
/// signature.
#[allow(dead_code)]
pub(crate) type TwainCallbackProc = DsmEntryProc;
/// `DSM_MEMALLOCATE`.
#[allow(dead_code)]
pub(crate) type DsmMemAllocate = unsafe extern "system" fn(size: u32) -> *mut c_void;
/// `DSM_MEMFREE`.
#[allow(dead_code)]
pub(crate) type DsmMemFree = unsafe extern "system" fn(handle: *mut c_void);
/// `DSM_MEMLOCK`.
#[allow(dead_code)]
pub(crate) type DsmMemLock = unsafe extern "system" fn(handle: *mut c_void) -> *mut c_void;
/// `DSM_MEMUNLOCK`.
#[allow(dead_code)]
pub(crate) type DsmMemUnlock = unsafe extern "system" fn(handle: *mut c_void);

/// `TW_ENTRYPOINT`: the DSM's entry point and memory functions.
#[allow(dead_code)]
#[repr(C, packed(2))]
#[derive(Clone, Copy, Default)]
pub(crate) struct TW_ENTRYPOINT {
    pub(crate) Size: u32,
    pub(crate) DSM_Entry: Option<DsmEntryProc>,
    pub(crate) DSM_MemAllocate: Option<DsmMemAllocate>,
    pub(crate) DSM_MemFree: Option<DsmMemFree>,
    pub(crate) DSM_MemLock: Option<DsmMemLock>,
    pub(crate) DSM_MemUnlock: Option<DsmMemUnlock>,
}

/// `TW_CALLBACK2`; `twain.h` types `CallBackProc` as a `TW_MEMREF`, a pointer
/// of the function pointer's size.
#[allow(dead_code)]
#[repr(C, packed(2))]
#[derive(Clone, Copy, Default)]
pub(crate) struct TW_CALLBACK2 {
    pub(crate) CallBackProc: Option<TwainCallbackProc>,
    pub(crate) RefCon: usize,
    pub(crate) Message: i16,
}

// The layouts MSVC gives twain.h's structs under `#pragma pack (2)`: the same
// in both bitnesses unless they hold a pointer. The header contract checks
// every field's offset; these catch the common mistakes at build time, on
// every system.
const _: () = {
    use core::mem::{offset_of, size_of};
    assert!(size_of::<TW_FIX32>() == 4);
    assert!(size_of::<TW_FRAME>() == 16);
    assert!(size_of::<TW_VERSION>() == 42);
    assert!(size_of::<TW_IDENTITY>() == 156);
    assert!(offset_of!(TW_IDENTITY, Version) == 4);
    assert!(offset_of!(TW_IDENTITY, ProtocolMajor) == 46);
    assert!(offset_of!(TW_IDENTITY, SupportedGroups) == 50);
    assert!(offset_of!(TW_IDENTITY, Manufacturer) == 54);
    assert!(offset_of!(TW_IDENTITY, ProductFamily) == 88);
    assert!(offset_of!(TW_IDENTITY, ProductName) == 122);
    assert!(size_of::<TW_ONEVALUE>() == 6);
    assert!(offset_of!(TW_ONEVALUE, Item) == 2);
    assert!(size_of::<TW_ENUMERATION>() == 16);
    assert!(offset_of!(TW_ENUMERATION, ItemList) == 14);
    assert!(size_of::<TW_ARRAY>() == 8);
    assert!(offset_of!(TW_ARRAY, ItemList) == 6);
    assert!(size_of::<TW_RANGE>() == 22);
    assert!(size_of::<TW_PENDINGXFERS>() == 6);
    assert!(size_of::<TW_IMAGEINFO>() == 42);
    assert!(offset_of!(TW_IMAGEINFO, BitsPerSample) == 18);
    assert!(offset_of!(TW_IMAGEINFO, PixelType) == 38);
    assert!(size_of::<TW_IMAGELAYOUT>() == 28);
    assert!(offset_of!(TW_IMAGELAYOUT, DocumentNumber) == 16);
    assert!(size_of::<TW_SETUPMEMXFER>() == 12);
    assert!(size_of::<TW_STATUS>() == 4);
    assert!(size_of::<TW_DEVICEEVENT>() == 294);
    assert!(offset_of!(TW_CAPABILITY, hContainer) == 4);
    assert!(offset_of!(TW_USERINTERFACE, hParent) == 4);
    assert!(offset_of!(TW_IMAGEMEMXFER, Memory) == 26);
    assert!(offset_of!(TW_MEMORY, TheMem) == 8);
    assert!(offset_of!(TW_INFO, Item) == 8);
    assert!(offset_of!(TW_EXTIMAGEINFO, Info) == 4);
    assert!(offset_of!(TW_ENTRYPOINT, DSM_Entry) == 4);
};

#[cfg(target_pointer_width = "64")]
const _: () = {
    use core::mem::{offset_of, size_of};
    assert!(size_of::<TW_CAPABILITY>() == 12);
    assert!(size_of::<TW_USERINTERFACE>() == 12);
    assert!(size_of::<TW_EVENT>() == 10);
    assert!(offset_of!(TW_EVENT, TWMessage) == 8);
    assert!(size_of::<TW_MEMORY>() == 16);
    assert!(size_of::<TW_IMAGEMEMXFER>() == 42);
    assert!(size_of::<TW_ENTRYPOINT>() == 44);
    assert!(size_of::<TW_CALLBACK2>() == 18);
    assert!(offset_of!(TW_CALLBACK2, RefCon) == 8);
    assert!(size_of::<TW_INFO>() == 16);
    assert!(size_of::<TW_EXTIMAGEINFO>() == 20);
};

#[cfg(target_pointer_width = "32")]
const _: () = {
    use core::mem::{offset_of, size_of};
    assert!(size_of::<TW_CAPABILITY>() == 8);
    assert!(size_of::<TW_USERINTERFACE>() == 8);
    assert!(size_of::<TW_EVENT>() == 6);
    assert!(offset_of!(TW_EVENT, TWMessage) == 4);
    assert!(size_of::<TW_MEMORY>() == 12);
    assert!(size_of::<TW_IMAGEMEMXFER>() == 38);
    assert!(size_of::<TW_ENTRYPOINT>() == 24);
    assert!(size_of::<TW_CALLBACK2>() == 10);
    assert!(offset_of!(TW_CALLBACK2, RefCon) == 4);
    assert!(size_of::<TW_INFO>() == 12);
    assert!(size_of::<TW_EXTIMAGEINFO>() == 16);
};
